//! Rebuilds this crate when a migration is added or changed, so that `MIGRATOR` (`sqlx::migrate!`, read at compile
//! time) always holds every migration – Cargo does not notice new files on its own. As generated by
//! `sqlx migrate build-script`.

fn main() {
    println!("cargo:rerun-if-changed=migrations");
}
